def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([9]), fmt([1, 1, 1]), fmt([3, 2, 1]), fmt([-5, 5, -5, 5]), fmt([0, 0, 1, 1, 2]),
             fmt([10**9, -10**9, 10**9]), fmt([4, 5, 6, 5, 4, 3, 5]), fmt([2, 1, 2, 1, 3, -1])]
    for n in (2, 3, 5, 8, 12, 20, 35):
        for _ in range(3):
            r = rng.choice([3, 6, 15, 100])
            tests.append(fmt([rng.randint(-r, r) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt([rng.randint(1, 50) for _ in range(N)]))
    tests.append(fmt([rng.randint(-1500, 1500) for _ in range(N)]))
    tests.append(fmt([int(1 + (rng.random() ** 3) * 20000) * rng.choice([-1, 1]) for _ in range(N)]))
    return tests

